import{_ as t,o as u,c as q,ag as e}from"./chunks/framework.B5ULsuav.js";const h=JSON.parse('{"title":"佛家金句","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/quote-佛家.md","filePath":"40-原话金句/quote-佛家.md","lastUpdated":1778155802000}'),a={name:"40-原话金句/quote-佛家.md"};function r(s,o,l,n,k,i){return u(),q("div",null,[...o[0]||(o[0]=[e('<h1 id="佛家金句" tabindex="-1">佛家金句 <a class="header-anchor" href="#佛家金句" aria-label="Permalink to &quot;佛家金句&quot;">​</a></h1><blockquote><p>了空居士讲解佛家经典（金刚经、心经、六祖坛经、公案）及佛学问答的精彩原话集 含：禅宗心法、般若智慧、净土念佛、公案启示</p></blockquote><hr><h2 id="一、心法总纲" tabindex="-1">一、心法总纲 <a class="header-anchor" href="#一、心法总纲" aria-label="Permalink to &quot;一、心法总纲&quot;">​</a></h2><blockquote><p><strong>&quot;保持平静的要诀就是保持理智地去看待一切。不平静的时候问自己：&#39;我为什么要不平静？这样的不平静正确吗？&#39;&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p></blockquote><blockquote><p><strong>&quot;应无所住而生其心——心不要停在任何一个地方，不停留才能生出真正的智慧。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p></blockquote><blockquote><p><strong>&quot;过去心不可得，现在心不可得，未来心不可得。过去已成过去，未来还没有来，现在却不断地在流动。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经18分-三心不可得">金刚经18分-三心不可得</a></p></blockquote><blockquote><p><strong>&quot;若见诸相非相，即见如来——看到一切现象都不是永恒的，你就见到真相了。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></p></blockquote><blockquote><p><strong>&quot;凡所有相，皆是虚妄。不是没有相，而是说所有的相都是假的、不永恒的，你不要被它骗了。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-离相">金刚经5分-离相</a></p></blockquote><hr><h2 id="二、对境不住" tabindex="-1">二、对境不住 <a class="header-anchor" href="#二、对境不住" aria-label="Permalink to &quot;二、对境不住&quot;">​</a></h2><blockquote><p><strong>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;——你一问，心就静下来了。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-保持平静的要诀">金刚经5分-保持平静的要诀</a></p></blockquote><blockquote><p><strong>&quot;知见无见，斯即涅槃——知道各种观点，但内心不执着于任何观点，这就是涅槃。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p></blockquote><blockquote><p><strong>&quot;要无住生心——该住就住，不该住就不住。吃饭就是吃饭，睡觉就是睡觉，不要一边吃饭一边想昨天的事。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p></blockquote><blockquote><p><strong>&quot;不怕念起，只怕觉迟。走神了，知道走神就不走神。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/答疑2021-不怕念起只怕觉迟">答疑2021-不怕念起只怕觉迟</a></p></blockquote><hr><h2 id="三、对法不执" tabindex="-1">三、对法不执 <a class="header-anchor" href="#三、对法不执" aria-label="Permalink to &quot;三、对法不执&quot;">​</a></h2><blockquote><p><strong>&quot;法尚应舍，何况非法——连佛法都要放下，何况那些不是法的东西。法是指南针，不是终点。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经6分-法尚应舍">金刚经6分-法尚应舍</a></p></blockquote><blockquote><p><strong>&quot;所谓佛法者，即非佛法——佛祖说的种种方法是对症下药，药方不能通用。不要将佛祖对甲说的话拿去给乙用。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经8分-佛法即非佛法">金刚经8分-佛法即非佛法</a></p></blockquote><blockquote><p><strong>&quot;无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说——没有一个固定的方法叫做开悟。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-无有定法">金刚经7分-无有定法</a></p></blockquote><blockquote><p><strong>&quot;庄严佛土者，即非庄严，是名庄严——做了一件好事，心里没有&#39;我在做好事&#39;的念头，这才是真正的庄严。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-应无所住生心">金刚经10分-应无所住生心</a></p></blockquote><blockquote><p><strong>&quot;实无有法名阿罗汉——不觉得自己证得了什么，才是真正的证得。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经9分-离欲与一相无相">金刚经9分-离欲与一相无相</a></p></blockquote><blockquote><p><strong>&quot;法无定法，各人因缘不同。千万不要拿自己的法门去评判别人的。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-无有定法">金刚经7分-无有定法</a></p></blockquote><blockquote><p><strong>&quot;我不守五戒，念佛有用吗？……有用。因果是一条一条来的。你虔诚念佛，就是跟佛结缘。因果是分毫不爽的，一条一条来的。&quot;</strong> ——答疑专辑2014_佛道</p></blockquote><blockquote><p><strong>&quot;从金刚经来说，修炼者不必执着有没有阿弥陀佛来接引。如果你真的能够一心念佛具足信愿，对一切相都不着，这是真正的上品上生。&#39;生则决定生，去则实不去&#39;。&quot;</strong> ——答疑专辑2014_佛道</p></blockquote><hr><h2 id="四、心经与般若" tabindex="-1">四、心经与般若 <a class="header-anchor" href="#四、心经与般若" aria-label="Permalink to &quot;四、心经与般若&quot;">​</a></h2><blockquote><p><strong>&quot;照见五蕴皆空——色受想行识都不是永恒的，看清楚它们都是空的，不是永恒的，度一切苦厄。&quot;</strong> ——心经讲解</p></blockquote><blockquote><p><strong>&quot;色不异空，空不异色——&#39;色&#39;和&#39;空&#39;是一回事。不是离开了色另外有空，也不是毁灭了色才叫空。现象本身就是空的。&quot;</strong> ——心经讲解</p></blockquote><blockquote><p><strong>&quot;是诸法空相——一切法的真实面目就是空相，不生不灭不垢不净不增不减。&quot;</strong> ——心经讲解</p></blockquote><blockquote><p><strong>&quot;菩提萨埵，依般若波罗蜜多故，心无挂碍——因为看透了，所以心里没有挂碍。无挂碍故，无有恐怖——没有挂碍就沒有恐惧。&quot;</strong> ——心经讲解</p></blockquote><blockquote><p><strong>&quot;远离颠倒梦想，究竟涅槃——颠倒就是把假的当成真的，把暂时的当成永恒的。远离了，就涅槃了。&quot;</strong> ——心经讲解</p></blockquote><hr><h2 id="五、禅宗与公案" tabindex="-1">五、禅宗与公案 <a class="header-anchor" href="#五、禅宗与公案" aria-label="Permalink to &quot;五、禅宗与公案&quot;">​</a></h2><blockquote><p><strong>&quot;寒山问拾得：世间谤我、欺我、辱我、笑我、轻我、贱我、恶我、骗我，如何处治乎？拾得曰：只是忍他、让他、由他、避他、耐他、敬他、不要理他，再待几年你且看他。&quot;</strong> ——公案系列（了空居士补充：&quot;忍让不是软弱，是看得破、放得下。&quot;）</p></blockquote><blockquote><p><strong>&quot;南泉斩猫——不是说真的要杀猫，是说要把心里的&#39;猫&#39;（执着）斩断。你心里的那只&#39;猫&#39;是什么？&quot;</strong> ——公案上_06_南泉斩猫</p></blockquote><blockquote><p><strong>&quot;赵州茶——&#39;吃茶去！&#39;修行就在喝茶吃饭日常之中，不在别处。&quot;</strong> ——公案上_07_吃茶去</p></blockquote><blockquote><p><strong>&quot;德山宣鉴——&#39;我宗无语句，实无一法与人&#39;。真正的佛法不立文字，不执一法。&quot;</strong> ——公案下_01_德山宣鉴</p></blockquote><blockquote><p><strong>&quot;庭前柏树子——佛法就在眼前普通的事物中，道无处不在。&quot;</strong> ——公案上_11_庭前柏树子</p></blockquote><blockquote><p><strong>&quot;归宗斩蛇——从蛇的角度看是杀生，从人类安全看是除害，从三世因果看是帮蛇少造罪业。跳出局部，看全局。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-整体观是非对错">金刚经7分-整体观是非对错</a></p></blockquote><hr><h2 id="六、自然务实" tabindex="-1">六、自然务实 <a class="header-anchor" href="#六、自然务实" aria-label="Permalink to &quot;六、自然务实&quot;">​</a></h2><blockquote><p><strong>&quot;一切贤圣，皆以无为法而有差别——方法有快慢，但都是为了到彼岸。坐飞机和走路都能到北京。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-无为法而有差别">金刚经7分-无为法而有差别</a></p></blockquote><blockquote><p><strong>&quot;信心不逆——真正相信了《金刚经》的道理，在做事时就会自觉&#39;以无我无人修一切善法&#39;。知行合一才是真信。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经15分-信心不逆">金刚经15分-信心不逆</a></p></blockquote><blockquote><p><strong>&quot;以无我无人无众生无寿者修一切善法，即得阿耨多罗三藐三菩提——不是先成佛再行善，而行善的同时就符合了成佛的标准。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经23分-净心行善">金刚经23分-净心行善</a></p></blockquote><blockquote><p><strong>&quot;认真工作也是禅定。生活处处是道场，为人处世样样是修行。&quot;</strong> ——修行即生活（20090111b）</p></blockquote><blockquote><p><strong>&quot;释迦牟尼佛六年苦修严格来说他连方向都摸不准，也不是渐悟。……他没有明师引路，是在黑暗中摸索。&quot;</strong> ——答疑专辑2014_佛道</p></blockquote><hr><h2 id="七、圆融中和" tabindex="-1">七、圆融中和 <a class="header-anchor" href="#七、圆融中和" aria-label="Permalink to &quot;七、圆融中和&quot;">​</a></h2><blockquote><p><strong>&quot;是故不应取法，不应取非法——不能执着于方法，也不能执着于&#39;一切都是空的&#39;。吃药好了就不吃了，病没好也不能不吃。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经6分-法尚应舍">金刚经6分-法尚应舍</a></p></blockquote><blockquote><p><strong>&quot;如来所说法，皆不可取，不可说——不要一听到什么就去抓住它，也不要一听到什么就说它不对。要具体问题具体分析。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经7分-非法非非法">金刚经7分-非法非非法</a></p></blockquote><blockquote><p><strong>&quot;若作是言：&#39;我当灭度无量众生&#39;，即不名菩萨——觉得自己&#39;度了很多人&#39;，那就还不是菩萨。度众生是分内之事，像父母养小孩一样自然。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经3分-四相与无我">金刚经3分-四相与无我</a></p></blockquote><hr><h2 id="八、历境炼心" tabindex="-1">八、历境炼心 <a class="header-anchor" href="#八、历境炼心" aria-label="Permalink to &quot;八、历境炼心&quot;">​</a></h2><blockquote><p><strong>&quot;一切法皆是佛法——不是做好事和做坏事没有区别，而是说只要不执着，一切现象都能成为觉悟的契机。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经17分-于法无所得">金刚经17分-于法无所得</a></p></blockquote><blockquote><p><strong>&quot;烦恼即菩提——烦恼不是敌人，它是你修行的机会。每一次烦恼来的时候，就是你进步的契机。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-烦恼即菩提">金刚经5分-烦恼即菩提</a></p></blockquote><blockquote><p><strong>&quot;六道皆是妄想所变幻出来，就犹如我们的开心和伤心变幻出笑容和泪水。你心情恢复平静了，开怀大笑的样子也不见了，眼泪汪汪也不见了。&quot;</strong> ——答疑专辑2014_佛道</p></blockquote><blockquote><p><strong>&quot;若复有人得闻是经，不惊不怖不畏——听到《金刚经》的道理不害怕，这个人就有大根器。因为这是要放下一切的。&quot;</strong> ——金刚经第14分</p></blockquote><hr><h2 id="九、天人合一" tabindex="-1">九、天人合一 <a class="header-anchor" href="#九、天人合一" aria-label="Permalink to &quot;九、天人合一&quot;">​</a></h2><blockquote><p><strong>&quot;佛说非身，是名大身——真正的&#39;大&#39;是跟宇宙一样大，你与万物为一体的那种大。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经10分-缘起性空">金刚经10分-缘起性空</a></p></blockquote><blockquote><p><strong>&quot;一滴水与大海融为一体——到底是大海得到一滴水，还是一滴水得到了大海？这就是一体。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/答疑2014-箩筐与大海">答疑2014-箩筐与大海</a></p></blockquote><blockquote><p><strong>&quot;若菩萨通达无我法者，如来说名真是菩萨——通达无我，做事都是自然流露，不图功德相，但也不是什么都不做。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经17分-于法无所得">金刚经17分-于法无所得</a></p></blockquote><blockquote><p><strong>&quot;心佛众生，三无差别。&quot;</strong> ——蔡衍颛文集</p></blockquote><hr><h2 id="十、修行心要" tabindex="-1">十、修行心要 <a class="header-anchor" href="#十、修行心要" aria-label="Permalink to &quot;十、修行心要&quot;">​</a></h2><blockquote><p><strong>&quot;《金刚经》的心法就是&#39;应无所住而生其心&#39;，具体应用就是&#39;若见诸相非相即见如来&#39;，为人处世怎么办？以无我、无人、无众生、无寿者，修一切善法。&quot;</strong> ——答疑专辑2014_佛道（三句话总结金刚经）</p></blockquote><blockquote><p><strong>&quot;开悟不是毕业，开悟是入学了。悟了之后还有很长的路要走，叫悟后起修。&quot;</strong> ——<a href="/liaokongjushi-wisdom/60-原文段落/金刚经5分-开悟与悟后迷">金刚经5分-开悟与悟后迷</a></p></blockquote><blockquote><p><strong>&quot;入静并不是说一念不生，一个念头都没有。真证禅定境界的人，心就如明镜高悬——鸟从镜子前飞过去，镜子里产生影子，鸟飞走了，影子也不见了。&quot;</strong> ——答疑专辑2019_修炼篇</p></blockquote><blockquote><p><strong>&quot;修行人最重要的是要有至诚恭敬之心。许多人以我为师，其实我心中也将我所遇到的每一个人当作师啊。&quot;</strong> ——论坛语录</p></blockquote><hr><h2 id="简短金句" tabindex="-1">简短金句 <a class="header-anchor" href="#简短金句" aria-label="Permalink to &quot;简短金句&quot;">​</a></h2><blockquote><p>&quot;做就是了。&quot; &quot;不怕念起，只怕觉迟。&quot; &quot;保持平静。&quot; &quot;当下即是。&quot; &quot;用心但不执着。&quot; &quot;诸恶莫作，众善奉行。&quot;</p></blockquote><hr><blockquote><p>来源：金刚经32讲、心经讲解、六祖坛经讲解、公案系列、答疑专辑2014/2019/2021 整理日期：2026-05-06 | 重构：2026-05-07（按佛家传统归并金刚经+心经+公案+答疑佛学；新增念佛、公案、修行心要金句15+条）</p></blockquote>',75)])])}const b=t(a,[["render",r]]);export{h as __pageData,b as default};
